#pragma once

#include "mdaz/types.hpp"

namespace mdaz {

class IPlatform;

// Static Sprite instances of a C2 layout (initial animation frame), drawn in layout order.
// Data: generated by tools/extract_layout_sprites.js.
class LayoutSprites {
public:
  static const int kMax = 256;

  LayoutSprites();
  bool load(IPlatform& platform, const char* path);
  int count() const { return count_; }
  void draw(IPlatform& platform, Vec2 cam, float scale, float view_w, float view_h) const;

private:
  struct Inst {
    char image[48];
    int sx, sy, sw, sh;
    float x, y, w, h, angle, hot_x, hot_y, opacity;
  };
  Inst inst_[kMax];
  int count_;
};

} // namespace mdaz
